document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("searchInput"),t=document.getElementById("searchResults");function n(e){if(!e.trim())return void(t.innerHTML='<div class="search-empty">Start typing to search the registry.</div>');const n=IRWR.searchRecords(IRWR_RECORDS,e);n.length?t.innerHTML=n.map(e=>`\n      <div class="search-row" data-id="${IRWR.escapeHtml(e.id)}">\n        <img class="photo" src="${IRWR.photoUrl(e,"",120,120)}" alt="${IRWR.escapeHtml(e.title)}" loading="lazy" width="120" height="120">\n        <div><strong>${IRWR.escapeHtml(e.title)}</strong><div>${IRWR.escapeHtml(e.holderName)} · ${IRWR.escapeHtml(e.country||"International")}</div></div>\n        <div>${IRWR.escapeHtml(e.category)}</div>\n        <div>${IRWR.escapeHtml(e.id)}</div>\n      </div>\n    `).join(""):t.innerHTML=`<div class="search-empty">No records match "${IRWR.escapeHtml(e)}".</div>`}t.addEventListener("click",e=>{const t=e.target.closest(".search-row");if(!t)return;const n=IRWR.byId(t.dataset.id);n&&IRWR.openRecordModal(n)}),e.addEventListener("input",()=>n(e.value)),n("")});